#!/usr/bin/env bash
# Host-CUDA-only second repair.  Its counterfactual source is generated by the
# actual bounded-DLS P1 proposal law, rather than random packets, so immediate
# candidate-versus-zero successor order is trained on the deployed support.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "${ROOT}"
SOURCE_ROOT="${1:-${ROOT}/data/reacher_official_source_20261024}"
PREVIOUS_RUN="${2:-${ROOT}/results/reacher_d2p_joint_repair_v1_20261024_cuda}"
RUN_ROOT="${3:-${ROOT}/results/reacher_d2p_p1_distribution_repair_v1_20261024_cuda}"
SOURCE_ROOT="$(cd "$(dirname "${SOURCE_ROOT}")" && pwd)/$(basename "${SOURCE_ROOT}")"
PREVIOUS_RUN="$(cd "$(dirname "${PREVIOUS_RUN}")" && pwd)/$(basename "${PREVIOUS_RUN}")"
RUN_ROOT="$(cd "$(dirname "${RUN_ROOT}")" && pwd)/$(basename "${RUN_ROOT}")"
SOURCE_MANIFEST="${SOURCE_ROOT}/official_source_manifest.json"
PREVIOUS_CHECKPOINT="${PREVIOUS_RUN}/checkpoint"
PREVIOUS_STATS="${PREVIOUS_RUN}/reacher_training_action_stats.json"
STATS="${RUN_ROOT}/reacher_training_action_stats.json"

if [[ -e "${RUN_ROOT}" ]]; then
  echo "refusing to overwrite immutable P1-distribution repair run: ${RUN_ROOT}" >&2
  exit 2
fi
if [[ ! -f "${SOURCE_MANIFEST}" || ! -f "${PREVIOUS_CHECKPOINT}/repair_manifest.json" || ! -f "${PREVIOUS_STATS}" ]]; then
  echo "official source, prior joint repair checkpoint, or training-action receipt is missing" >&2
  exit 2
fi
jq -e '(.schema == "reacher_d2p_joint_transition_counterfactual_repair.v1") and (.status == "trained_joint_source_only") and (.training_contract.p0_p1_roots_used == false)' "${PREVIOUS_CHECKPOINT}/repair_manifest.json" >/dev/null
DATASET="$(jq -er '.dataset' "${SOURCE_MANIFEST}")"
[[ -s "${DATASET}" ]]

nvidia-smi --query-gpu=name,driver_version --format=csv,noheader
mkdir -p "${RUN_ROOT}"
cp "${PREVIOUS_STATS}" "${STATS}"
.venv/bin/python -m experiments.spectral_reachability.build_reacher_d2p_p1_proposal_pair_pool \
  --output "${RUN_ROOT}/counterfactual_pool" --policy "${PREVIOUS_CHECKPOINT}" --adapter-artifact "${STATS}" \
  --seed 20268100 --roots 64 --damping 10 --proposals 128 --device cuda
.venv/bin/python -m experiments.spectral_reachability.train_reacher_d2p_joint_repair \
  --dataset "${DATASET}" --pair-pool "${RUN_ROOT}/counterfactual_pool/pairs.h5" --pair-manifest "${RUN_ROOT}/counterfactual_pool/manifest.json" \
  --adapter-artifact "${STATS}" --base-checkpoint "${PREVIOUS_CHECKPOINT}" --output "${RUN_ROOT}/checkpoint" \
  --seed 20268201 --epochs 8 --transition-batch-size 32 --pair-batch-size 8 --steps-per-epoch 128 --learning-rate 1e-5 --counterfactual-weight 1 --device cuda
.venv/bin/python -m experiments.spectral_reachability.preflight_reacher_d2p_p0 \
  --policy "${RUN_ROOT}/checkpoint" --adapter-artifact "${STATS}" --device cuda --seed 20269700 --roots 4 --output "${RUN_ROOT}/p0_preflight"
for damping in 0.001 0.01 0.1 1 10; do
  .venv/bin/python -m experiments.spectral_reachability.run_reacher_d2p_p0_goal_progress \
    --policy "${RUN_ROOT}/checkpoint" --adapter-artifact "${STATS}" --device cuda --seed 20269800 --roots 4 --calibration-roots 4 --calibration-only --damping "${damping}" --output "${RUN_ROOT}/p0_calibration_d${damping}"
done
.venv/bin/python -m experiments.spectral_reachability.select_reacher_d2p_damping \
  --reports "${RUN_ROOT}/p0_calibration_d0.001/report.json" "${RUN_ROOT}/p0_calibration_d0.01/report.json" "${RUN_ROOT}/p0_calibration_d0.1/report.json" "${RUN_ROOT}/p0_calibration_d1/report.json" "${RUN_ROOT}/p0_calibration_d10/report.json" --output "${RUN_ROOT}/p0_damping_selection.json"
DAMPING="$(jq -er '.selected.damping' "${RUN_ROOT}/p0_damping_selection.json")"
.venv/bin/python -m experiments.spectral_reachability.run_reacher_d2p_p0_goal_progress \
  --policy "${RUN_ROOT}/checkpoint" --adapter-artifact "${STATS}" --device cuda --seed 20269900 --roots 12 --calibration-roots 0 --outcome-only --damping "${DAMPING}" --calibration-evidence "${RUN_ROOT}/p0_damping_selection.json" --output "${RUN_ROOT}/p0_outcome"
if [[ "$(jq -r '.stage_gate.p1_unlocked' "${RUN_ROOT}/p0_outcome/report.json")" != "true" ]]; then
  echo "P0 did not unlock P1; preserve the sealed result and stop." >&2
  exit 3
fi
.venv/bin/python -m experiments.spectral_reachability.preflight_reacher_d2p_p1_reconfiguration \
  --policy "${RUN_ROOT}/checkpoint" --adapter-artifact "${STATS}" --device cuda --seed 20270000 --roots 4 --p0-evidence "${RUN_ROOT}/p0_outcome/report.json" --damping "${DAMPING}" --output "${RUN_ROOT}/p1_preflight"
.venv/bin/python -m experiments.spectral_reachability.run_reacher_d2p_p1_reconfiguration \
  --policy "${RUN_ROOT}/checkpoint" --adapter-artifact "${STATS}" --device cuda --seed 20270100 --roots 6 --calibration-only --p0-evidence "${RUN_ROOT}/p0_outcome/report.json" --p1-preflight-evidence "${RUN_ROOT}/p1_preflight" --damping "${DAMPING}" --mechanism-observability observed_encoded_goal_cost --training-source-manifest "${RUN_ROOT}/checkpoint/repair_manifest.json" --output "${RUN_ROOT}/p1_calibration"
.venv/bin/python -m experiments.spectral_reachability.audit_reacher_d2p_p1_first_chunk_fidelity \
  --policy "${RUN_ROOT}/checkpoint" --adapter-artifact "${STATS}" --report "${RUN_ROOT}/p1_calibration/report.json" --output "${RUN_ROOT}/p1_first_chunk_fidelity.json"
if [[ "$(jq -r '.gates.every_model_eligible_reconfiguration_is_observably_non_greedy_relative_to_zero_prefix' "${RUN_ROOT}/p1_calibration/report.json")" != "true" ]] || ! jq -e '(.status == "completed") and (.summary.eligible_roots_audited > 0) and (.summary.model_to_observation_goal_order_agreement_count == .summary.eligible_roots_audited) and ([.gates[]] | all)' "${RUN_ROOT}/p1_first_chunk_fidelity.json" >/dev/null; then
  echo "P1-distribution repair did not preserve every first-chunk model-to-observation order; outcome roots remain sealed." >&2
  exit 4
fi
.venv/bin/python -m experiments.spectral_reachability.run_reacher_d2p_p1_reconfiguration \
  --policy "${RUN_ROOT}/checkpoint" --adapter-artifact "${STATS}" --device cuda --seed 20270200 --roots 12 --outcome-only --calibration-evidence "${RUN_ROOT}/p1_calibration/report.json" --p0-evidence "${RUN_ROOT}/p0_outcome/report.json" --p1-preflight-evidence "${RUN_ROOT}/p1_preflight" --damping "${DAMPING}" --mechanism-observability observed_encoded_goal_cost --training-source-manifest "${RUN_ROOT}/checkpoint/repair_manifest.json" --output "${RUN_ROOT}/p1_outcome"
